export type ParsedCreateMarketInstruction<
  TProgram extends string = typeof STOCK_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    config: TAccountMetas[1];
    collateralMint: TAccountMetas[2];
    usdcMint: TAccountMetas[3];
    market: TAccountMetas[4];
    collateralVault: TAccountMetas[5];
    usdcVault: TAccountMetas[6];
    collateralTokenProgram: TAccountMetas[7];
    usdcTokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: CreateMarketInstructionData;
};

export function parseCreateMarketInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCreateMarketInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      config: getNextAccount(),
      collateralMint: getNextAccount(),
      usdcMint: getNextAccount(),
      market: getNextAccount(),
      collateralVault: getNextAccount(),
      usdcVault: getNextAccount(),
      collateralTokenProgram: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getCreateMarketInstructionDataDecoder().decode(instruction.data),
  };
}
